    }
    const px = p.x;
    const py = groundY + p.yOffset - 31 * S;
    if (Math.hypot(b.x - px, b.y - py) < (18 + b.radius) * S) {
      if (damagePlayer(b.kind === "drone" ? 8 : 7, b.x, b.y)) {
        game.bullets.splice(i, 1);
      }
    }
  }
}

