  // =========================================================
  //  RENDER — background
  // =========================================================
  function drawSmokeBlob(x, y, r, alpha, color = "36,41,40") {
    ctx.fillStyle = `rgba(${color},${alpha})`;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.ellipse(
        x + (i - 1.5) * r * 0.38,
        y - Math.abs(i - 1.5) * r * 0.1,
        r * (0.55 + i * 0.08),
        r * (0.18 + i * 0.02),
        (i - 1.5) * 0.08,
        0,
        TAU
      );
      ctx.fill();
    }
  }

  function drawSky() {
    const sky = ctx.createLinearGradient(0, 0, 0, groundY + 20);
    sky.addColorStop(0, "#0a1116");
    sky.addColorStop(0.32, "#172126");
    sky.addColorStop(0.58, "#2d3130");
    sky.addColorStop(0.78, "#514235");
    sky.addColorStop(1, "#74543a");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, groundY + 22);

    const sx = W * 0.73;
    const sy = H * 0.31;
    const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, W * 0.42);
    glow.addColorStop(0, "rgba(255,173,91,0.31)");
    glow.addColorStop(0.22, "rgba(241,137,64,0.16)");
    glow.addColorStop(0.58, "rgba(180,92,48,0.06)");
    glow.addColorStop(1, "rgba(80,50,35,0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, W, groundY + 10);

    const haze = ctx.createLinearGradient(0, H * 0.44, 0, groundY + 8);
    haze.addColorStop(0, "rgba(188,135,84,0)");
    haze.addColorStop(0.68, "rgba(177,123,75,0.09)");
    haze.addColorStop(1, "rgba(206,145,86,0.17)");
    ctx.fillStyle = haze;
    ctx.fillRect(0, H * 0.44, W, groundY - H * 0.44 + 8);

    // Slow smoke banks across the horizon.
    const wo = game.scroll * 0.018;
    for (let i = -1; i < 8; i++) {
      const x = mod(i * W * 0.21 - wo + game.menuTime * 2.5, W + 520) - 260;
      const y = H * (0.11 + hash(i * 5 + 3) * 0.31);
      drawSmokeBlob(x, y, 95 + hash(i * 7 + 2) * 150, 0.055 + hash(i + 9) * 0.035, "44,49,47");
    }

    // Low burning haze.
    const low = ctx.createRadialGradient(W * 0.64, groundY - 10, 0, W * 0.64, groundY - 10, W * 0.38);
    low.addColorStop(0, "rgba(255,152,74,0.08)");
    low.addColorStop(1, "rgba(255,152,74,0)");
    ctx.fillStyle = low;
    ctx.fillRect(0, H * 0.42, W, groundY - H * 0.42);
  }

  function drawFarCity() {
    const p = 0.075;
    const spacing = 98;
    const wo = game.scroll * p;
    const start = Math.floor(wo / spacing) - 2;
    const end = start + Math.ceil(W / spacing) + 4;
    const base = groundY - 8;

    for (let gi = start; gi <= end; gi++) {
      const x = gi * spacing - wo;
      const r = hash(gi * 1.17 + 8);
      const w = 42 + r * 48;
      const h = 26 + hash(gi * 2.31 + 4) * 96;
      const broken = hash(gi * 4.7 + 1);
      ctx.fillStyle = `rgba(17,26,30,${0.78 + r * 0.14})`;
      ctx.beginPath();
      ctx.moveTo(x, base);
      ctx.lineTo(x, base - h * 0.75);
      if (broken > 0.68) {
        ctx.lineTo(x + w * 0.22, base - h * 0.75);
        ctx.lineTo(x + w * 0.22, base - h * 0.58);
        ctx.lineTo(x + w * 0.45, base - h * 0.58);
      }
      ctx.lineTo(x + w * 0.45, base - h);
      if (broken > 0.4) {
        ctx.lineTo(x + w * 0.68, base - h);
        ctx.lineTo(x + w * 0.68, base - h * 0.82);
      }
      ctx.lineTo(x + w, base - h * 0.82);
      ctx.lineTo(x + w, base);
      ctx.closePath();
      ctx.fill();

      if (h > 72) {
        ctx.strokeStyle = "rgba(14,21,24,0.85)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x + w * 0.5, base - h);
        ctx.lineTo(x + w * 0.5, base - h - 15);
        ctx.stroke();
      }

      const cols = Math.floor(w / 13);
      const rows = Math.floor(h / 19);
      for (let cx = 0; cx < cols; cx++) {
        for (let cy = 0; cy < rows; cy++) {
          if (hash(gi * 17 + cx * 5 + cy * 11) > 0.82) {
            ctx.fillStyle = `rgba(255,157,70,${0.12 + hash(gi + cx + cy) * 0.22})`;
            ctx.fillRect(x + 7 + cx * 12, base - h + 11 + cy * 18, 2, 3);
          }
        }
      }
    }
  }

  function drawMidGround() {
    const p = 0.28;
    const spacing = 232;
    const wo = game.scroll * p;
    const start = Math.floor(wo / spacing) - 2;
    const end = start + Math.ceil(W / spacing) + 4;
    const base = groundY - 3;

    for (let gi = start; gi <= end; gi++) {
      const x = gi * spacing - wo;
      const r = hash(gi * 3.7 + 21);
      if (r < 0.2) continue;
      const w = 85 + hash(gi * 1.9 + 4) * 100;
      const h = 54 + hash(gi * 2.4 + 13) * 128;
      const topCut = hash(gi * 5.1 + 7);
      ctx.fillStyle = `rgba(11,19,21,${0.9 + r * 0.08})`;
      ctx.beginPath();
      ctx.moveTo(x, base);
      ctx.lineTo(x, base - h * 0.72);
      ctx.lineTo(x + w * 0.13, base - h * 0.72);
      ctx.lineTo(x + w * 0.13, base - h * 0.9);
      ctx.lineTo(x + w * 0.35, base - h * 0.9);
      if (topCut > 0.45) {
        ctx.lineTo(x + w * 0.35, base - h * 0.66);
        ctx.lineTo(x + w * 0.52, base - h * 0.66);
      }
      ctx.lineTo(x + w * 0.52, base - h);
      ctx.lineTo(x + w * 0.78, base - h);
