  // =========================================================
  //  RENDER — characters & vehicles
  // =========================================================
  const PAL_PLAYER = {
    uniform: "#465033", uniformDark: "#303824", vest: "#262e20",
    skin: "#bd9069", skinDark: "#8f6549", helmet: "#333a2b",
    boot: "#171a14", pack: "#2d3424", accent: "#3b83ff", accent2: "#ffd23f",
  };
  const PAL_ENEMY = {
