  // =========================================================
  //  RENDER — scene composition
  // =========================================================
  function drawPlayer() {
    const p = game.player;
    if (!p || p.hidden) return;
    const foot = groundY + p.yOffset;
    const shadowScale = clamp(1 + p.yOffset / (H * 0.8), 0.45, 1);
    ctx.save();
    ctx.globalAlpha = 0.42 * shadowScale;
    ctx.fillStyle = "#000";
    ctx.beginPath();
    ctx.ellipse(p.x, groundY + 2, 23 * S * shadowScale, 5 * S * shadowScale, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    const flicker = p.invuln > 0 && p.dodge <= 0 ? 0.62 + Math.abs(Math.sin(game.menuTime * 44)) * 0.38 : 1;

    if (p.dodge > 0) {
      const ghostOpts = {
        run: p.run, moving: true, air: !p.grounded, dodge: p.dodge,
        aim: p.aim, muzzle: 0,
      };
      ctx.save();
      ctx.globalAlpha = 0.1 * flicker;
      drawSoldier(p.x - 15 * S, foot, ghostOpts);
      ctx.globalAlpha = 0.06 * flicker;
      drawSoldier(p.x - 29 * S, foot, ghostOpts);
      ctx.restore();
    }

    drawSoldier(p.x, foot, {
      run: p.run,
      moving: p.grounded || game.state === "extraction",
      air: !p.grounded,
      dodge: p.dodge,
      muzzle: p.muzzle,
      aim: p.aim,
      dead: p.dead,
      alpha: flicker,
    });
  }

  function drawExtractionScene() {
    const ex = game.extraction;
    if (!ex) return;
    const sV = clamp(Math.min(W / 900, H / 760) * 1.2, 0.78, 1.35);

    drawNovator(ex.vehicleX, {
      moving: ex.phase === "drive" ? ex.driveT + 0.2 : 0,
      muzzle: ex.vehicleMuzzle,
    });

    // Green smoke marks the rear ramp.
    for (let i = 0; i < 5; i++) {
      const drift = Math.sin(game.menuTime * 0.8 + i * 0.7) * (4 + i * 2);
      drawSmokeBlob(
        ex.vehicleX - (100 + i * 2) * sV + drift,
        groundY - 8 - i * 13,
        10 + i * 4,
        0.09 - i * 0.012,
        "89,153,104"
      );
    }

    // Two comrades lay down covering fire, then board.
    for (let i = 0; i < 2; i++) {
      let cx = ex.vehicleX - (124 + i * 30) * S;
      let cy = groundY;
      let hidden = false;
      const start = i === 0 ? 0.1 : 0.42;
      const t = ex.boardT - start;
      if (ex.phase === "board" && t > 0) {
        const k = clamp(t / 0.55, 0, 1);
        cx = lerp(cx, ex.vehicleX - 58 * S, k);
        cy = groundY - Math.sin(k * Math.PI) * 46 * S;
        if (t > 0.58) hidden = true;
      }
      if (hidden) continue;
      drawSoldier(cx, cy, {
        run: game.menuTime * 9 + i * 2,
        moving: ex.phase !== "board",
        air: ex.phase === "board" && t > 0,
        muzzle: ex.comradeMuzzle[i],
        aim: 0.02,
        scale: S * 0.94,
      });
    }

    drawPlayer();

    drawTracers();
    drawBullets();
    drawShocks();

    // Extraction marker over the ramp.
    if (ex.phase === "arrive" || ex.phase === "run") {
      const pulse = 0.55 + Math.sin(game.menuTime * 3.5) * 0.22;
      const mx = ex.vehicleX - 82 * sV;
      const my = groundY - 105 * sV + Math.sin(game.menuTime * 2.2) * 4;
      ctx.save();
      ctx.globalAlpha = pulse;
      ctx.fillStyle = "#77e4a2";
      ctx.beginPath();
      ctx.moveTo(mx, my + 14);
      ctx.lineTo(mx - 8, my);
      ctx.lineTo(mx + 8, my);
      ctx.closePath();
      ctx.fill();
      ctx.font = "700 7px ui-monospace, monospace";
      ctx.textAlign = "center";
      ctx.fillText("EXTRACT", mx, my - 7);
      ctx.restore();
    }
  }

  function drawMenuScene() {
    const idleX = W > 820 ? W * 0.71 : W * 0.78;
    const p = game.player;
    if (p) {
      ctx.save();
      ctx.globalAlpha = 0.34;
      ctx.fillStyle = "#000";
      ctx.beginPath();
      ctx.ellipse(idleX, groundY + 2, 23 * S, 5 * S, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
      drawSoldier(idleX, groundY, {
        run: p.run * 0.45,
        moving: false,
        aim: -0.02,
        muzzle: 0,
      });
    }

    const d = game.menuDrone;
    const fakeDrone = {
      x: d.x,
      y: d.y + Math.sin(d.bob) * 7,
      rotor: d.rotor,
      bob: d.bob,
      size: 1.15,
      hp: 5,
      maxHp: 5,
      dead: false,
      hitFlash: 0,
      warning: 0,
      muzzle: 0,
      rot: 0,
    };
    drawDrone(fakeDrone);

    // A faint second contact, far out.
    drawDrone({
      x: W * 0.94,
      y: H * 0.16,
      rotor: d.rotor * 0.7,
      bob: d.bob + 2,
      size: 0.65,
      hp: 5,
      maxHp: 5,
      dead: false,
      hitFlash: 0,
      warning: 0,
      muzzle: 0,
      rot: 0,
    });
  }

  function drawBattleScene() {
    for (const e of game.enemies) drawGroundEnemy(e);
    for (const d of game.drones) drawDrone(d);
    drawPlayer();
    drawTracers();
    drawBullets();
    drawStrikes();
    drawShocks();
  }

  function drawScreenFlash() {
    if (game.flash <= 0.002) return;
    ctx.save();
    ctx.fillStyle = `rgba(${game.flashColor},${clamp(game.flash * 0.32, 0, 0.32)})`;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  function render() {
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.clearRect(0, 0, W, H);

    ctx.save();
    if (game.shake > 0.25) {
      ctx.translate(rand(-game.shake, game.shake), rand(-game.shake, game.shake));
    }

    drawSky();
    drawFarCity();
    drawMidGround();
    drawNearGround();
    drawGround();
    drawParticles("bg");

    if (game.state === "menu") {
      drawMenuScene();
    } else if (game.state === "extraction" || game.state === "victory") {
      drawExtractionScene();
    } else {
      drawBattleScene();
    }

    drawParticles("fg");
    drawAsh();
    ctx.restore();
    drawScreenFlash();
  }

  // =========================================================
  //  BOOT
  // =========================================================
  let lastFrame = performance.now();

  function loop(now) {
    let dt = (now - lastFrame) / 1000;
    lastFrame = now;
    if (!Number.isFinite(dt) || dt < 0) dt = 0;
    dt = Math.min(dt, 0.05);
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  resize();
  game.player = createPlayer();
  game.menuDrone.x = W * 0.82;
  game.menuDrone.y = H * 0.24;
  updateHud();
  updateSoundButton();
  requestAnimationFrame(loop);
})();

