function drawSky() {
  const sky = ctx.createLinearGradient(0, 0, 0, groundY + 20);
  sky.addColorStop(0, "#0d151b");
  sky.addColorStop(0.3, "#1c292f");
  sky.addColorStop(0.55, "#384043");
  sky.addColorStop(0.76, "#655241");
  sky.addColorStop(1, "#8a6244");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, groundY + 22);

  const sx = W * 0.73;
  const sy = H * 0.31;
  const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, W * 0.46);
  glow.addColorStop(0, "rgba(255,186,106,0.4)");
  glow.addColorStop(0.18, "rgba(248,151,72,0.21)");
  glow.addColorStop(0.55, "rgba(192,105,56,0.09)");
  glow.addColorStop(1, "rgba(80,50,35,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, groundY + 10);

  const haze = ctx.createLinearGradient(0, H * 0.4, 0, groundY + 8);
  haze.addColorStop(0, "rgba(208,150,96,0)");
  haze.addColorStop(0.66, "rgba(198,139,87,0.13)");
  haze.addColorStop(1, "rgba(230,161,95,0.24)");
  ctx.fillStyle = haze;
  ctx.fillRect(0, H * 0.4, W, groundY - H * 0.4 + 8);

  const wo = game.scroll * 0.018;
  for (let i = -1; i < 8; i++) {
    const x = mod(i * W * 0.21 - wo + game.menuTime * 2.5, W + 520) - 260;
    const y = H * (0.11 + hash(i * 5 + 3) * 0.31);
    drawSmokeBlob(x, y, 95 + hash(i * 7 + 2) * 150, 0.07 + hash(i + 9) * 0.045, "52,57,55");
  }

  // A flare drifts down beyond the skyline, trailing smoke.
  const flareX = W * 0.82 + Math.sin(game.menuTime * 0.24) * W * 0.035;
  const flareY = H * 0.16 + mod(game.menuTime * 7.5, H * 0.28);
  const flare = ctx.createRadialGradient(flareX, flareY, 0, flareX, flareY, 62);
  flare.addColorStop(0, "rgba(255,246,190,0.8)");
  flare.addColorStop(0.12, "rgba(255,192,95,0.42)");
  flare.addColorStop(0.48, "rgba(255,130,65,0.12)");
  flare.addColorStop(1, "rgba(255,120,55,0)");
  ctx.fillStyle = flare;
  ctx.beginPath();
  ctx.arc(flareX, flareY, 62, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(92,91,78,0.14)";
  ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.moveTo(flareX + 4, flareY - 6);
  ctx.quadraticCurveTo(flareX - 16, flareY - 78, flareX + 2, flareY - 145);
  ctx.stroke();

  const low = ctx.createRadialGradient(W * 0.64, groundY - 10, 0, W * 0.64, groundY - 10, W * 0.38);
  low.addColorStop(0, "rgba(255,152,74,0.13)");
  low.addColorStop(1, "rgba(255,152,74,0)");
  ctx.fillStyle = low;
  ctx.fillRect(0, H * 0.42, W, groundY - H * 0.42);
}

