    ctx.fillRect(15, -1.4, 10, 0.8);
    if (muzzle > 0) {
      drawMuzzleFlash(30, 0, 0, 0.9 + muzzle * 4, "255,222,145");
    }
    ctx.restore();

    ctx.strokeStyle = pal.uniformDark;
    ctx.lineWidth = 4.2;
    ctx.beginPath();
    ctx.moveTo(5, -43);
    ctx.lineTo(13, -40.5);
    ctx.stroke();

    ctx.restore();
  }

  function drawDrone(d) {
    const s = S * (d.size || 1);
    const bob = d.dead ? 0 : Math.sin(d.bob) * 3;
    const px = d.x;
    const py = d.y + bob;

    if (!d.dead) {
      const p = game.player;
      if (d.warning > 0 && p) {
        const alpha = 0.12 + Math.abs(Math.sin(game.menuTime * 18)) * 0.28;
        ctx.save();
        ctx.strokeStyle = `rgba(255,72,52,${alpha})`;
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 7]);
        ctx.beginPath();
        ctx.moveTo(px, py + 8 * s);
        ctx.lineTo(p.x, groundY + p.yOffset - 31 * S);
        ctx.stroke();
        ctx.restore();
      }

      ctx.save();
      ctx.globalAlpha = clamp(0.3 - (groundY - py) / H * 0.22, 0.05, 0.26);
      ctx.fillStyle = "#000";
      ctx.beginPath();
      ctx.ellipse(px, groundY + 2, 22 * s, 5 * s, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    ctx.save();
    ctx.translate(px, py);
    if (d.dead) ctx.rotate(d.rot);
    ctx.scale(s, s);
    const hot = d.hitFlash > 0;

    const arms = [
      [-15, -7, -26, -14],
      [15, -7, 26, -14],
      [-15, 7, -26, 14],
      [15, 7, 26, 14],
    ];
    ctx.strokeStyle = "#121817";
    ctx.lineWidth = 2.8;
    ctx.lineCap = "round";
    for (const a of arms) {
      ctx.beginPath();
      ctx.moveTo(a[0] * 0.45, a[1] * 0.45);
      ctx.lineTo(a[2], a[3]);
      ctx.stroke();
      ctx.save();
      ctx.translate(a[2], a[3]);
      ctx.rotate(d.rotor + a[0] * 0.04);
      ctx.fillStyle = "rgba(174,195,193,0.18)";
      ctx.beginPath();
      ctx.ellipse(0, 0, 12, 2.3, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = "rgba(206,224,218,0.22)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(0, 0, 12, 2.3, 0, 0, TAU);
      ctx.stroke();
      ctx.restore();
    }

    ctx.fillStyle = hot ? "#a6b1ae" : "#252d2c";
    ctx.beginPath();
    ctx.moveTo(-11, -7);
    ctx.lineTo(-7, -12);
    ctx.lineTo(7, -12);
    ctx.lineTo(11, -7);
    ctx.lineTo(10, 7);
    ctx.lineTo(5, 11);
    ctx.lineTo(-5, 11);
    ctx.lineTo(-10, 7);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#080c0b";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = "rgba(255,255,255,0.07)";
    ctx.beginPath();
    ctx.moveTo(-6, -9);
    ctx.lineTo(6, -9);
    ctx.lineTo(4, -5);
    ctx.lineTo(-4, -5);
    ctx.closePath();
    ctx.fill();

    ctx.save();
    ctx.shadowColor = "rgba(255,52,38,0.9)";
    ctx.shadowBlur = 10;
    ctx.fillStyle = hot ? "#fff" : "#ff3b2f";
    ctx.beginPath();
    ctx.arc(0, 1, 2.7, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = "rgba(255,68,52,0.5)";
    ctx.fillRect(-8, 6, 3, 1.2);

    ctx.strokeStyle = "#141a19";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(0, -12);
    ctx.lineTo(-1, -19);
    ctx.stroke();
    ctx.fillStyle = "#ff5a42";
    ctx.beginPath();
    ctx.arc(-1, -19.5, 1.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#171c1a";
    roundRectPath(ctx, -3, 10, 6, 5, 1.5);
    ctx.fill();

    if (d.muzzle > 0) drawMuzzleFlash(0, 14, Math.PI / 2, 0.55, "255,105,70");
    ctx.restore();

    if (!d.dead && d.hp < d.maxHp) {
      const w = 34 * s;
      ctx.fillStyle = "rgba(3,7,8,0.75)";
      ctx.fillRect(px - w / 2, py - 26 * s, w, 3);
      ctx.fillStyle = "#ff5548";
      ctx.fillRect(px - w / 2 + 1, py - 25 * s, (w - 2) * clamp(d.hp / d.maxHp, 0, 1), 1.4);
    }
  }

  function drawGroundEnemy(e) {
    const p = game.player;
    const y = groundY;
    ctx.save();
    ctx.globalAlpha = clamp(0.28 - Math.abs(e.x - p.x) / W * 0.1, 0.08, 0.25);
    ctx.fillStyle = "#000";
    ctx.beginPath();
    ctx.ellipse(e.x, groundY + 2, 19 * S, 4.5 * S, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    drawSoldier(e.x, y, {
      enemy: true,
      facing: -1,
      run: e.run,
      moving: !e.dead && e.x > p.x + 115 * S,
      air: false,
      dead: e.dead,
      aim: 0.03,
      muzzle: e.muzzle,
      alpha: e.dead ? 1 : (e.frozen ? 0.75 : 1),
    });

    if (!e.dead && e.hp < e.maxHp) {
      const w = 32 * S;
      ctx.fillStyle = "rgba(3,7,8,0.72)";
      ctx.fillRect(e.x - w / 2, groundY - 74 * S, w, 3);
      ctx.fillStyle = "#ff6b58";
      ctx.fillRect(e.x - w / 2 + 1, groundY - 73 * S, (w - 2) * clamp(e.hp / e.maxHp, 0, 1), 1.4);
    }
  }

  function drawNovator(x, opts = {}) {
    const s = clamp(Math.min(W / 900, H / 760) * 1.2, 0.78, 1.35);
    const moving = opts.moving || 0;
    const muzzle = opts.muzzle || 0;
    ctx.save();
    ctx.translate(x, groundY + 1);
    ctx.scale(s, s);

    ctx.fillStyle = "rgba(0,0,0,0.48)";
    ctx.beginPath();
    ctx.ellipse(0, 4, 124, 13, 0, 0, TAU);
    ctx.fill();

    for (let i = 0; i < 6; i++) {
      const wx = -84 + i * 34;
      ctx.fillStyle = "#080b0a";
      ctx.beginPath();
      ctx.arc(wx, -16, 15, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = "#252b24";
      ctx.lineWidth = 3.5;
      ctx.beginPath();
      ctx.arc(wx, -16, 10, 0, TAU);
      ctx.stroke();
      ctx.save();
      ctx.translate(wx, -16);
      ctx.rotate(moving * 1.6 + i);
      ctx.strokeStyle = "rgba(128,137,114,0.28)";
      ctx.lineWidth = 1.4;
      for (let k = 0; k < 3; k++) {
        ctx.rotate(TAU / 3);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(0, -8);
        ctx.stroke();
      }
      ctx.restore();
    }

    const hull = ctx.createLinearGradient(0, -72, 0, -18);
    hull.addColorStop(0, "#49543c");
    hull.addColorStop(0.45, "#343d2c");
    hull.addColorStop(1, "#22281d");
    ctx.fillStyle = hull;
    ctx.beginPath();
    ctx.moveTo(-112, -19);
    ctx.lineTo(-106, -60);
    ctx.lineTo(-82, -70);
    ctx.lineTo(72, -70);
    ctx.lineTo(103, -51);
    ctx.lineTo(114, -26);
    ctx.lineTo(108, -18);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#151a12";
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = "rgba(13,18,12,0.4)";
    ctx.fillRect(-98, -56, 40, 27);
    ctx.fillStyle = "rgba(104,112,78,0.16)";
    ctx.fillRect(-54, -62, 52, 7);
    ctx.fillStyle = "rgba(19,24,15,0.35)";
    ctx.beginPath();
    ctx.ellipse(-40, -43, 23, 9, -0.2, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(40, -37, 18, 7, 0.2, 0, TAU);
    ctx.fill();

    ctx.fillStyle = "#0c1212";
    ctx.fillRect(48, -59, 22, 11);
    ctx.fillStyle = "rgba(141,180,176,0.14)";
    ctx.fillRect(50, -57, 18, 3);
    ctx.strokeStyle = "rgba(12,16,11,0.65)";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-8, -70);
    ctx.lineTo(-8, -56);
    ctx.lineTo(30, -56);
    ctx.stroke();

    ctx.fillStyle = "#293023";
    ctx.beginPath();
    ctx.moveTo(-112, -52);
    ctx.lineTo(-92, -55);
    ctx.lineTo(-92, -20);
    ctx.lineTo(-108, -20);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(8,11,8,0.8)";
    ctx.lineWidth = 1.2;
    ctx.stroke();

    ctx.fillStyle = "rgba(218,225,196,0.52)";
    ctx.font = "700 8px ui-monospace, monospace";
    ctx.textAlign = "center";
    ctx.fillText("NOVATOR", -34, -28);
    ctx.fillStyle = "#2f72e8";
    ctx.fillRect(-91, -79, 16, 5);
    ctx.fillStyle = "#ffd23f";
    ctx.fillRect(-91, -74, 16, 5);
    ctx.strokeStyle = "rgba(0,0,0,0.5)";
    ctx.lineWidth = 0.8;
    ctx.strokeRect(-91, -79, 16, 10);

    ctx.fillStyle = "#3e4833";
    ctx.beginPath();
    ctx.moveTo(0, -70);
    ctx.lineTo(46, -70);
    ctx.lineTo(52, -80);
    ctx.lineTo(30, -88);
    ctx.lineTo(-6, -87);
    ctx.lineTo(-12, -79);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#141910";
    ctx.lineWidth = 1.6;
    ctx.stroke();
    ctx.fillStyle = "#1c2218";
    roundRectPath(ctx, -6, -89, 19, 5, 2);
    ctx.fill();

    ctx.strokeStyle = "#171c14";
    ctx.lineWidth = 4.4;
    ctx.beginPath();
    ctx.moveTo(32, -80);
    ctx.lineTo(92, -81);
    ctx.stroke();
    ctx.strokeStyle = "rgba(190,200,168,0.2)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(34, -81.5);
    ctx.lineTo(91, -82.5);
    ctx.stroke();

    ctx.fillStyle = "rgba(255,225,150,0.9)";
    ctx.fillRect(109, -43, 3, 4);
    ctx.fillStyle = "rgba(255,70,55,0.8)";
    ctx.fillRect(-109, -44, 2.5, 3);

    if (muzzle > 0) drawMuzzleFlash(94, -81, 0, 1.2, "255,220,140");
    ctx.restore();
  }

  // =========================================================
  //  RENDER — scene composition
  // =========================================================
  function drawPlayer() {
    const p = game.player;
    if (!p || p.hidden) return;
    const foot = groundY + p.yOffset;
    const shadowScale = clamp(1 + p.yOffset / (H * 0.8), 0.45, 1);
    ctx.save();
    ctx.globalAlpha = 0.42 * shadowScale;
    ctx.fillStyle = "#000";
    ctx.beginPath();
    ctx.ellipse(p.x, groundY + 2, 23 * S * shadowScale, 5 * S * shadowScale, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    const flicker = p.invuln > 0 && p.dodge <= 0 ? 0.62 + Math.abs(Math.sin(game.menuTime * 44)) * 0.38 : 1;

    if (p.dodge > 0) {
      const ghostOpts = {
        run: p.run, moving: true, air: !p.grounded, dodge: p.dodge,
        aim: p.aim, muzzle: 0,
      };
      ctx.save();
      ctx.globalAlpha = 0.1 * flicker;
      drawSoldier(p.x - 15 * S, foot, ghostOpts);
      ctx.globalAlpha = 0.06 * flicker;
      drawSoldier(p.x - 29 * S, foot, ghostOpts);
      ctx.restore();
    }

    drawSoldier(p.x, foot, {
      run: p.run,
      moving: p.grounded || game.state === "extraction",
      air: !p.grounded,
      dodge: p.dodge,
      muzzle: p.muzzle,
      aim: p.aim,
      dead: p.dead,
      alpha: flicker,
    });
  }

  function drawExtractionScene() {
    const ex = game.extraction;
    if (!ex) return;
    const sV = clamp(Math.min(W / 900, H / 760) * 1.2, 0.78, 1.35);

    drawNovator(ex.vehicleX, {
      moving: ex.phase === "drive" ? ex.driveT + 0.2 : 0,
      muzzle: ex.vehicleMuzzle,
    });

    // Green smoke marks the rear ramp.
    for (let i = 0; i < 5; i++) {
      const drift = Math.sin(game.menuTime * 0.8 + i * 0.7) * (4 + i * 2);
      drawSmokeBlob(
        ex.vehicleX - (100 + i * 2) * sV + drift,
        groundY - 8 - i * 13,
        10 + i * 4,
        0.09 - i * 0.012,
        "89,153,104"
      );
    }

    // Two comrades lay down covering fire, then board.
    for (let i = 0; i < 2; i++) {
      let cx = ex.vehicleX - (124 + i * 30) * S;
      let cy = groundY;
      let hidden = false;
      const start = i === 0 ? 0.1 : 0.42;
      const t = ex.boardT - start;
      if (ex.phase === "board" && t > 0) {
        const k = clamp(t / 0.55, 0, 1);
        cx = lerp(cx, ex.vehicleX - 58 * S, k);
        cy = groundY - Math.sin(k * Math.PI) * 46 * S;
        if (t > 0.58) hidden = true;
      }
      if (hidden) continue;
      drawSoldier(cx, cy, {
        run: game.menuTime * 9 + i * 2,
        moving: ex.phase !== "board",
        air: ex.phase === "board" && t > 0,
        muzzle: ex.comradeMuzzle[i],
        aim: 0.02,
        scale: S * 0.94,
      });
    }

    drawPlayer();

    drawTracers();
    drawBullets();
    drawShocks();

    // Extraction marker over the ramp.
    if (ex.phase === "arrive" || ex.phase === "run") {
      const pulse = 0.55 + Math.sin(game.menuTime * 3.5) * 0.22;
      const mx = ex.vehicleX - 82 * sV;
      const my = groundY - 105 * sV + Math.sin(game.menuTime * 2.2) * 4;
      ctx.save();
      ctx.globalAlpha = pulse;
      ctx.fillStyle = "#77e4a2";
      ctx.beginPath();
      ctx.moveTo(mx, my + 14);
      ctx.lineTo(mx - 8, my);
      ctx.lineTo(mx + 8, my);
      ctx.closePath();
      ctx.fill();
      ctx.font = "700 7px ui-monospace, monospace";
      ctx.textAlign = "center";
      ctx.fillText("EXTRACT", mx, my - 7);
      ctx.restore();
    }
  }

  function drawMenuScene() {
    const idleX = W > 820 ? W * 0.71 : W * 0.78;
    const p = game.player;
    if (p) {
      ctx.save();
      ctx.globalAlpha = 0.34;
      ctx.fillStyle = "#000";
      ctx.beginPath();
      ctx.ellipse(idleX, groundY + 2, 23 * S, 5 * S, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
      drawSoldier(idleX, groundY, {
        run: p.run * 0.45,
        moving: false,
        aim: -0.02,
        muzzle: 0,
      });
    }

    const d = game.menuDrone;
    const fakeDrone = {
      x: d.x,
      y: d.y + Math.sin(d.bob) * 7,
      rotor: d.rotor,
      bob: d.bob,
      size: 1.15,
      hp: 5,
      maxHp: 5,
      dead: false,
      hitFlash: 0,
      warning: 0,
      muzzle: 0,
      rot: 0,
    };
    drawDrone(fakeDrone);

    // A faint second contact, far out.
    drawDrone({
      x: W * 0.94,
      y: H * 0.16,
      rotor: d.rotor * 0.7,
      bob: d.bob + 2,
      size: 0.65,
      hp: 5,
      maxHp: 5,
      dead: false,
      hitFlash: 0,
      warning: 0,
      muzzle: 0,
      rot: 0,
    });
  }

  function drawBattleScene() {
    for (const e of game.enemies) drawGroundEnemy(e);
    for (const d of game.drones) drawDrone(d);
    drawPlayer();
    drawTracers();
    drawBullets();
    drawStrikes();
    drawShocks();
  }

  function drawScreenFlash() {
    if (game.flash <= 0.002) return;
    ctx.save();
    ctx.fillStyle = `rgba(${game.flashColor},${clamp(game.flash * 0.32, 0, 0.32)})`;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  function render() {
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.clearRect(0, 0, W, H);

    ctx.save();
    if (game.shake > 0.25) {
      ctx.translate(rand(-game.shake, game.shake), rand(-game.shake, game.shake));
    }

    drawSky();
    drawFarCity();
    drawMidGround();
    drawNearGround();
    drawGround();
    drawParticles("bg");

    if (game.state === "menu") {
      drawMenuScene();
    } else if (game.state === "extraction" || game.state === "victory") {
      drawExtractionScene();
    } else {
      drawBattleScene();
    }

    drawParticles("fg");
    drawAsh();
    ctx.restore();
    drawScreenFlash();
  }

  // =========================================================
  //  BOOT
  // =========================================================
  let lastFrame = performance.now();

  function loop(now) {
    let dt = (now - lastFrame) / 1000;
    lastFrame = now;
    if (!Number.isFinite(dt) || dt < 0) dt = 0;
    dt = Math.min(dt, 0.05);
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  resize();
  game.player = createPlayer();
  game.menuDrone.x = W * 0.82;
  game.menuDrone.y = H * 0.24;
  updateHud();
  updateSoundButton();
  requestAnimationFrame(loop);
})();

:root {
  --blue: #3b83ff;
  --blue-hot: #75adff;
  --yellow: #ffd23f;
  --yellow-hot: #ffe27a;
  --ink: #060a0b;
  --panel: rgba(7, 13, 15, 0.72);
  --panel-solid: rgba(8, 15, 17, 0.92);
  --line: rgba(228, 239, 233, 0.16);
  --line-bright: rgba(228, 239, 233, 0.32);
  --text: #edf1ec;
  --muted: #94a19b;
  --muted-2: #67736e;
  --red: #ff5548;
  --green: #77e4a2;
  --shadow: 0 14px 50px rgba(0, 0, 0, 0.42);
  --display: "Arial Narrow", "Roboto Condensed", "Liberation Sans Narrow", "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Liberation Mono", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #050808;
  color: var(--text);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--yellow);
  outline-offset: 3px;
}

.app {
  position: fixed;
  inset: 0;
  isolation: isolate;
  background: #050808;
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

.fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.fx-grain {
  z-index: 8;
  opacity: 0.085;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  animation: grain-shift 0.8s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(2%, 2%, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

.fx-vignette {
  z-index: 7;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 42%, rgba(2, 5, 6, 0.32) 72%, rgba(1, 3, 4, 0.82) 100%),
    linear-gradient(to bottom, rgba(3, 7, 8, 0.5), transparent 16%, transparent 72%, rgba(2, 5, 6, 0.5));
}

.fx-damage {
  z-index: 9;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 36%, rgba(185, 20, 14, 0.55) 100%);
}

.fx-damage.hit {
  animation: damage-pulse 0.48s ease-out;
}

@keyframes damage-pulse {
  0% { opacity: 0.9; }
  100% { opacity: 0; }
}

/* =========================================================
   HUD
   ========================================================= */

.hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  padding: max(14px, env(safe-area-inset-top)) clamp(12px, 2vw, 28px) max(14px, env(safe-area-inset-bottom));
  padding: max(14px, env(safe-area-inset-top)) clamp(12px, 2vw, 28px) max(14px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-6px);
  transition: opacity 0.4s ease, transform 0.4s ease, visibility 0.4s;
}

.is-playing .hud,
.is-ended .hud {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.is-ended .hud {
  opacity: 0.28;
}

.topbar {
  display: grid;
  grid-template-columns: minmax(190px, 270px) minmax(280px, 560px) auto;
  gap: clamp(10px, 1.4vw, 20px);
  align-items: start;
  justify-content: space-between;
}

.panel {
  position: relative;
  border: 1px solid var(--line);
  background:
    linear-gradient(135deg, rgba(31, 45, 47, 0.32), transparent 36%),
    var(--panel);
  box-shadow: var(--shadow), inset 0 0 0 1px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(9px) saturate(0.7);
