function die() {
  if (game.state === "dead") return;
  game.state = "dead";
  game.deathTimer = 0;
  game.health = 0;
  game.player.dead = true;
  game.player.vy = -220;
  game.player.grounded = false;
  game.flash = Math.max(game.flash, 0.45);
  game.flashColor = "255,70,55";
