      color: "110,180,255", gravity: 0, drag: 1,
    });
  }
}

function explode(x, y, size = 1, color = "255,150,70") {
  game.shocks.push({
    x, y,
    r: 4 * size,
    maxR: 52 * size * S,
    life: 0.42,
    max: 0.42,
    color,
    width: 2.6 * size,
  });
  const sparks = Math.round(11 * size);
  for (let i = 0; i < sparks; i++) {
    const a = rand(0, TAU);
    const sp = rand(80, 340) * size;
    addParticle({
      type: "spark",
      x, y,
      vx: Math.cos(a) * sp,
      vy: Math.sin(a) * sp - rand(20, 100),
      size: rand(1.2, 3.1),
      life: rand(0.2, 0.65),
      color,
      gravity: 520,
      drag: 1.6,
    });
  }
  for (let i = 0; i < Math.round(6 * size); i++) {
    addParticle({
      type: "smoke",
      x: x + rand(-10, 10) * size,
      y: y + rand(-10, 10) * size,
      vx: rand(-55, 55) * size,
      vy: rand(-85, -15) * size,
      size: rand(7, 18) * size,
      life: rand(0.7, 1.6),
      color: i % 3 === 0 ? "54,55,50" : "77,71,60",
      grow: rand(16, 30),
      drag: 0.8,
    });
  }
  for (let i = 0; i < Math.round(4 * size); i++) {
    addParticle({
      type: "ember",
      x, y,
      vx: rand(-120, 120) * size,
      vy: rand(-180, -50) * size,
      size: rand(1, 2.6),
      life: rand(0.5, 1.2),
      color: "255,190,90",
      gravity: 200,
      drag: 0.7,
    });
  }
  game.shake = Math.min(26, game.shake + 3.5 * size);
  game.flash = Math.max(game.flash, 0.12 * size);
  game.flashColor = color;
}

function addBgFlash(x, y, size = 1) {
  game.particles.push({
    type: "flash", x, y, vx: 0, vy: 0,
    size: 60 * size * S, life: 0.5, max: 0.5,
    color: "255,164,80", gravity: 0, drag: 0,
    layer: "bg", rot: 0, vr: 0,
  });
  for (let i = 0; i < 4; i++) {
    addParticle({
      type: "smoke",
      x: x + rand(-20, 20), y: y + rand(-6, 6),
