function loop(now) {
  let dt = (now - lastFrame) / 1000;
  lastFrame = now;
  if (game.state === "menu") {
    requestAnimationFrame(loop);
    return;
  }
  if (!Number.isFinite(dt) || dt < 0) dt = 0;
  dt = Math.min(dt, 0.05);
  update(dt);
  render();
  requestAnimationFrame(loop);
}

